package com.tecsup;
import java.util.*; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import jakarta.validation.constraints.Pattern; import org.springframework.validation.annotation.Validated;
@RestController @Validated @RequestMapping("/api/pedidos") public class PedidoController { private final PedidoRepository repo; private final ClienteClient clientes; private final ProductoClient productos; public PedidoController(PedidoRepository r,ClienteClient c,ProductoClient p){repo=r;clientes=c;productos=p;} private PedidoResponse response(Pedido x){return new PedidoResponse(x.id,x.cantidad,x.estado,clientes.get(x.clienteId),productos.get(x.productoId));} @GetMapping public List<PedidoResponse> all(){return repo.findAll().stream().map(this::response).toList();} @GetMapping("/{id}") public PedidoResponse one(@PathVariable Long id){return response(repo.findById(id).orElseThrow());} @PostMapping public PedidoResponse create(@Valid @RequestBody Pedido x){x.id=null;if(x.estado==null)x.estado="PENDIENTE";return response(repo.save(x));} @PatchMapping("/{id}/estado") public Pedido update(@PathVariable Long id,@RequestParam @Pattern(regexp="PENDIENTE|ATENDIDO|ANULADO") String estado){Pedido x=repo.findById(id).orElseThrow();x.estado=estado;return repo.save(x);} }
